<?php
require_once 'config/layout.php';
require_once 'config/guidance.php';
require_login();
$id=filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT) ?: 0;
$stmt=db()->prepare('SELECT * FROM recommendations WHERE id=? AND user_id=?');$stmt->execute([$id,(int)$_SESSION['user_id']]);$rec=$stmt->fetch();
if (!$rec) { http_response_code(404); page_start('Career not found','careers'); echo '<main id="main" class="wide page-space"><div class="panel"><h1>Career match not found</h1><p>This recommendation is not available for this account.</p><a class="btn btn-primary" href="dashboard.php">Return to dashboard</a></div></main>';page_end();exit; }
$error='';$saved=false;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??null);$rating=filter_var($_POST['rating']??null,FILTER_VALIDATE_INT);$comment=is_string($_POST['comment']??null)?trim($_POST['comment']):'';if(!$rating||$rating<1||$rating>5||mb_strlen($comment)>1000)$error='Choose a rating from 1 to 5 and keep comments under 1000 characters.';else{db()->prepare('INSERT INTO recommendation_feedback(user_id,recommendation_id,rating,comment) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE rating=VALUES(rating),comment=VALUES(comment)')->execute([(int)$_SESSION['user_id'],$id,$rating,$comment]);$saved=true;}}
$s=db()->prepare('SELECT payload FROM recommendation_details WHERE recommendation_id=?');$s->execute([$id]);$details=json_array($s->fetchColumn()?:'[]');
$progs=json_decode($rec['local_programmes'] ?? '[]',true)?:[];
page_start($rec['career_title'],'careers');
?>
<main id="main" class="wide page-space"><a href="dashboard.php" class="back-link">← Your matches</a><section class="career-hero"><span class="eyebrow">YOUR CAREER MATCH</span><h1><?= e($rec['career_title']) ?></h1><p>Explore why this career was suggested and what it could take to get there.</p><span class="big-score"><?= round((float)$rec['match_score']) ?>% <small>approximate match</small></span></section><div class="two-column"><div class="side-stack"><section class="panel"><span class="eyebrow muted-eyebrow">YOUR EXPLANATION</span><h2>Why this may fit you</h2><p class="readable-text"><?= nl2br(e($rec['explanation'])) ?></p></section><section class="panel"><span class="eyebrow muted-eyebrow">YOUR LEARNING PATH</span><h2>Useful subjects to explore</h2><p class="readable-text"><?= e($rec['recommended_subjects']) ?></p><p class="fine-print">Suggested subjects are general guidance, not officially verified admission requirements.</p></section></div><div class="side-stack"><section class="panel"><span class="eyebrow muted-eyebrow">OPTIONS CLOSE TO HOME</span><h2>Possible Lesotho programmes</h2><?php if ($progs): ?><div class="programme-list"><?php foreach ($progs as $p): ?><div class="programme-item"><strong><?= e($p['programme'] ?? '') ?></strong><span><?= e($p['university'] ?? '') ?> · <?= e($p['level'] ?? '') ?></span><?php if (!empty($p['missing_subjects'])): ?><small>Subjects not listed in your profile: <?= e(implode(', ',$p['missing_subjects'])) ?></small><?php endif; ?><small class="unverified"><?= !empty($p['verified'])?e($p['verification_scope']??'Source checked; confirm current requirements with the institution.'):'Unverified legacy sample. Check all details with the institution.' ?></small><?= source_link($p) ?></div><?php endforeach; ?></div><?php else: ?><p>No matching local programmes are listed in the current reference data. Ask your teacher or check local prospectuses for related qualifications.</p><?php endif; ?></section><section class="panel"><h3>Typical education information</h3><p class="muted"><?= e($rec['education_level'] ?? 'Not available') ?></p><p class="fine-print">Typical education estimates come from an international occupational dataset and may differ in Lesotho.</p><a href="chat.php" class="btn btn-outline">Ask a follow-up question ↗</a></section></div></div><section class="panel tool-links"><h2>Explore this option</h2><dl class="score-grid"><div><dt>Interest alignment</dt><dd><?= isset($details['interest_alignment'])?e((string)$details['interest_alignment']).'%':'Unknown (legacy or missing data)' ?></dd></div><div><dt>Academic preparation</dt><dd><?= isset($details['academic_preparation'])?e((string)$details['academic_preparation']).'%':'Unknown' ?></dd></div><div><dt>Subject compatibility</dt><dd><?= isset($details['subject_compatibility'])?e((string)$details['subject_compatibility']).'%':'Unknown' ?></dd></div></dl><p class="fine-print">Heuristic preparation scores are separate from admission eligibility. Scores are not probabilities.</p><p><?= e(t('Exploration notice')) ?></p><?php if(!empty($details['component_scores'])):?><div class="table-scroll"><table><caption>How your weighted match was calculated</caption><thead><tr><th>Component</th><th>Score / 100</th><th>Effective weight</th></tr></thead><tbody><?php foreach($details['component_scores'] as $component=>$value):?><tr><td><?= e(ucfirst($component)) ?></td><td><?= $value===null?'Not available':e((string)$value) ?></td><td><?= round(100*($details['effective_weights'][$component]??0),1) ?>%</td></tr><?php endforeach;?></tbody></table></div><?php endif;?><?= saved_button('career',$rec['career_title'],$rec['career_title']) ?><a class="btn btn-outline" href="compare.php?career=<?= e(urlencode($rec['career_title'])) ?>">Compare this career</a><a class="btn btn-primary" href="roadmap.php?career=<?= e(urlencode($rec['career_title'])) ?>">Create my roadmap</a></section><section class="panel"><h2>Was this recommendation useful?</h2><?php if($error):?><p class="alert error" role="alert"><?= e($error) ?></p><?php endif;?><?php if($saved):?><p class="alert success" role="status">Feedback saved. Thank you.</p><?php endif;?><form method="post" class="form-grid"><?= csrf_field() ?><label>Usefulness<select name="rating" required><option value="">Choose a rating</option><option value="1">1 — Not useful</option><option value="2">2 — Slightly useful</option><option value="3">3 — Moderately useful</option><option value="4">4 — Useful</option><option value="5">5 — Very useful</option></select></label><label>Optional feedback<textarea name="comment" maxlength="1000" rows="3"></textarea><small>Avoid private personal details. Feedback measures perceived usefulness, not prediction accuracy.</small></label><button class="btn btn-primary">Save feedback</button></form></section></main>
<?php page_end(); ?>



